    }

    .topbar {
      padding: 1rem 0 0.5rem;
      color: var(--muted);
      font-size: 0.92rem;
    }

    .topbar__inner {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: center;
      flex-wrap: wrap;
    }

    .topbar__badge {
