      align-items: center;
      gap: 0.5rem;
      padding: 0.4rem 0.75rem;
      border: 1px solid var(--border);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.03);
    }

    .topbar__dot {
      width: 0.55rem;
      height: 0.55rem;
      border-radius: 50%;
      background: var(--accent-strong);
      box-shadow: 0 0 0 6px rgba(92, 200, 255, 0.14);
    }

    header {
      padding: 0.5rem 0 1.4rem;
    }

    .header-bar {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1.5rem;
      padding: 1rem 0 1.2rem;
      border-bottom: 1px solid var(--border);
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.8rem;
      text-decoration: none;
      font-weight: 700;
      letter-spacing: 0.02em;
    }

    .brand__mark {
      display: grid;
      place-items: center;
      width: 2.5rem;
      height: 2.5rem;
      border-radius: 14px;
      background: linear-gradient(135deg, rgba(141, 220, 255, 0.28), rgba(255, 184, 107, 0.22));
      border: 1px solid rgba(255, 255, 255, 0.14);
      box-shadow: inset 0 1px 0 rgba(255,255,255,0.08);
      color: var(--text);
    }

    nav[aria-label="Primary"] ul {
      display: flex;
      flex-wrap: wrap;
      gap: 0.35rem;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    nav[aria-label="Primary"] a {
      display: inline-flex;
      align-items: center;
      min-height: 44px;
      padding: 0.4rem 0.9rem;
      border-radius: 999px;
      color: var(--muted);
      text-decoration: none;
      transition: background-color 160ms ease, color 160ms ease, border-color 160ms ease;
      border: 1px solid transparent;
    }

    nav[aria-label="Primary"] a:hover,
    nav[aria-label="Primary"] a:focus-visible {
      color: var(--text);
      border-color: var(--border);
      background: rgba(255, 255, 255, 0.04);
    }

    .hero {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 1.25rem;
      padding: 1.25rem 0 2rem;
      align-items: stretch;
    }

    .hero__content,
    .hero__panel,
    .section-card,
    .feature-card,
    .deal-card,
    .editorial-card {
      border: 1px solid var(--border);
      background: linear-gradient(180deg, rgba(24, 29, 42, 0.95), rgba(14, 17, 24, 0.95));
      box-shadow: var(--shadow);
      backdrop-filter: blur(16px);
    }

    .hero__content {
      border-radius: var(--radius-lg);
      padding: clamp(1.5rem, 3vw, 2.5rem);
      display: grid;
      gap: 1.1rem;
      align-content: center;
      min-height: 100%;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      width: fit-content;
      padding: 0.4rem 0.75rem;
      border-radius: 999px;
      background: rgba(92, 200, 255, 0.1);
      border: 1px solid rgba(92, 200, 255, 0.18);
      color: #cceeff;
      font-size: 0.88rem;
      letter-spacing: 0.03em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      content: "";
      width: 0.45rem;
      height: 0.45rem;
      border-radius: 50%;
      background: var(--accent-strong);
      box-shadow: 0 0 0 4px rgba(92, 200, 255, 0.14);
    }

    h1 {
      margin: 0;
      font-size: clamp(2.4rem, 5vw, 4.6rem);
      line-height: 0.98;
      letter-spacing: -0.05em;
      max-width: 12ch;
    }

    .lede {
      margin: 0;
      max-width: 56ch;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .hero__actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.8rem;
      margin-top: 0.2rem;
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.55rem;
      min-height: 48px;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      border: 1px solid transparent;
      font: inherit;
      font-weight: 600;
      text-decoration: none;
      cursor: pointer;
    }

    .button--primary {
      background: linear-gradient(135deg, var(--accent-strong), #8fffe0);
      color: #071019;
      box-shadow: 0 16px 30px rgba(92, 200, 255, 0.18);
    }

    .button--primary:hover,
    .button--primary:focus-visible {
      color: #071019;
      filter: brightness(1.03);
    }

    .button--secondary {
      color: var(--text);
      background: rgba(255, 255, 255, 0.04);
      border-color: var(--border);
    }

    .button--secondary:hover,
    .button--secondary:focus-visible {
      background: rgba(255, 255, 255, 0.07);
      color: var(--text);
    }

    .hero__stats {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.8rem;
      margin-top: 0.35rem;
    }

    .stat {
      padding: 0.9rem;
      border-radius: var(--radius-sm);
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.06);
    }

    .stat strong {
      display: block;
      font-size: 1.05rem;
      margin-bottom: 0.2rem;
    }

    .stat span {
      color: var(--muted);
      font-size: 0.94rem;
    }

    .hero__panel {
      border-radius: var(--radius-lg);
      overflow: hidden;
      display: grid;
      align-content: stretch;
      min-height: 100%;
    }

    .spotlight {
      position: relative;
      padding: 1.25rem;
      display: grid;
      gap: 1rem;
      min-height: 100%;
      background:
        radial-gradient(circle at 20% 18%, rgba(92, 200, 255, 0.18), transparent 28%),
        radial-gradient(circle at 80% 12%, rgba(255, 184, 107, 0.15), transparent 24%),
        linear-gradient(180deg, rgba(19, 24, 38, 0.98), rgba(10, 13, 18, 0.98));
    }

    .spotlight__visual {
      min-height: 300px;
      border-radius: 24px;
      background:
        radial-gradient(circle at 50% 42%, rgba(255, 255, 255, 0.24), transparent 16%),
        radial-gradient(circle at 50% 55%, rgba(141, 220, 255, 0.28), transparent 24%),
        linear-gradient(145deg, #22293c, #0c111a 60%, #1d2434);
      border: 1px solid rgba(255, 255, 255, 0.1);
      position: relative;
      overflow: hidden;
    }

    .spotlight__visual::before,
    .spotlight__visual::after {
      content: "";
      position: absolute;
      inset: auto;
      border-radius: 999px;
      background: rgba(141, 220, 255, 0.22);
      filter: blur(6px);
    }

    .spotlight__visual::before {
      width: 9rem;
      height: 9rem;
      left: 1rem;
      bottom: 1.2rem;
      background: radial-gradient(circle, rgba(255, 184, 107, 0.7), rgba(255, 184, 107, 0.08) 68%, transparent 70%);
      opacity: 0.75;
    }

    .spotlight__visual::after {
      width: 11rem;
      height: 11rem;
      right: -0.5rem;
      top: 1.2rem;
      background: radial-gradient(circle, rgba(92, 200, 255, 0.9), rgba(92, 200, 255, 0.08) 66%, transparent 70%);
      opacity: 0.28;
    }

    .spotlight__card {
      position: absolute;
      left: 1rem;
      right: 1rem;
      bottom: 1rem;
      padding: 1rem;
      border-radius: 20px;
      background: rgba(10, 13, 20, 0.78);
      border: 1px solid rgba(255, 255, 255, 0.1);
      backdrop-filter: blur(14px);
    }

    .spotlight__card h2 {
      margin: 0 0 0.35rem;
      font-size: 1.1rem;
    }

    .spotlight__card p {
      margin: 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .sections {
      display: grid;
      gap: 1.25rem;
      padding-bottom: 2.5rem;
    }

    .section-card {
      border-radius: var(--radius-lg);
      padding: clamp(1.1rem, 2vw, 1.5rem);
    }

    .section-head {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: end;
      margin-bottom: 1rem;
    }

    .section-head h2,
    .section-head h3 {
      margin: 0;
      font-size: clamp(1.35rem, 2.4vw, 2rem);
      letter-spacing: -0.03em;
    }

    .section-head p {
      margin: 0;
      color: var(--muted);
      max-width: 48ch;
    }

    .grid {
      display: grid;
      gap: 1rem;
    }

    .products-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .feature-card,
    .deal-card,
    .editorial-card {
      border-radius: 22px;
      overflow: hidden;
    }

    .feature-card {
      display: grid;
      grid-template-rows: 210px auto;
    }

    .feature-card__image {
      position: relative;
      background: linear-gradient(145deg, #1b2132, #0d1118 70%);
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    }

    .feature-card__image::before,
    .feature-card__image::after {
      content: "";
      position: absolute;
      inset: auto;
      border-radius: 999px;
      opacity: 0.9;
    }

    .feature-card__image::before {
      left: 18%;
      top: 16%;
      width: 56%;
      height: 60%;
      background: radial-gradient(circle at 50% 36%, rgba(255, 255, 255, 0.28), rgba(255,255,255,0.06) 44%, transparent 46%);
      filter: blur(0.5px);
    }

    .feature-card__image::after {
      right: 12%;
      bottom: 12%;
      width: 6rem;
      height: 6rem;
      background: radial-gradient(circle, rgba(255, 184, 107, 0.95), rgba(255, 184, 107, 0.04) 70%, transparent 72%);
      box-shadow: 0 0 0 24px rgba(255, 184, 107, 0.06);
    }

    .feature-card__body,
    .deal-card__body,
    .editorial-card__body {
      padding: 1rem;
    }

    .product-meta,
    .deal-meta {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      color: var(--muted);
      font-size: 0.92rem;
      margin-bottom: 0.7rem;
    }

    .price {
      color: var(--text);
      font-weight: 700;
    }

    .feature-card h3,
    .deal-card h3,
    .editorial-card h3 {
      margin: 0 0 0.45rem;
      font-size: 1.12rem;
    }

    .feature-card p,
    .deal-card p,
    .editorial-card p {
      margin: 0;
      color: var(--muted);
    }

    .tag-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.45rem;
      margin-top: 0.85rem;
    }

    .tag {
      display: inline-flex;
      align-items: center;
      min-height: 32px;
      padding: 0.25rem 0.6rem;
      border-radius: 999px;
      font-size: 0.82rem;
      color: #d4def0;
      background: rgba(255, 255, 255, 0.05);
      border: 1px solid rgba(255, 255, 255, 0.08);
    }

    .deals-grid {
      grid-template-columns: 1.1fr 0.9fr 0.9fr;
    }

    .deal-card {
      display: grid;
      grid-template-columns: 0.95fr 1.05fr;
      min-height: 100%;
      background:
        radial-gradient(circle at top left, rgba(255, 184, 107, 0.14), transparent 34%),
        linear-gradient(180deg, rgba(24, 29, 42, 0.95), rgba(12, 15, 21, 0.95));
    }

    .deal-card__visual {
      min-height: 100%;
      background:
        radial-gradient(circle at 30% 28%, rgba(255, 255, 255, 0.15), transparent 18%),
        linear-gradient(160deg, rgba(92, 200, 255, 0.18), rgba(12, 15, 21, 0.12) 38%, rgba(255, 184, 107, 0.14));
      border-right: 1px solid rgba(255, 255, 255, 0.08);
      position: relative;
    }

    .deal-card__visual::after {
      content: "";
      position: absolute;
      inset: 18% 18%;
      border-radius: 20px;
      background:
        linear-gradient(145deg, rgba(10, 13, 19, 0.85), rgba(29, 36, 52, 0.92));
      border: 1px solid rgba(255, 255, 255, 0.08);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
    }

    .deal-card--wide {
      grid-template-columns: 1fr;
    }

    .deal-card--wide .deal-card__visual {
      min-height: 180px;
      border-right: 0;
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    }

    .deal-card--wide .deal-card__visual::after {
      inset: 18% 10% 20%;
    }

    .deal-card__body {
      display: grid;
      align-content: start;
      gap: 0.85rem;
    }

    .deal-card__footer {
      display: flex;
      flex-wrap: wrap;
      gap: 0.65rem;
      align-items: center;
      margin-top: 0.2rem;
    }

    .deal-card__footer .button {
      min-height: 42px;
      padding-inline: 0.85rem;
    }

    .deal-chip {
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      width: fit-content;
      min-height: 34px;
      padding: 0.3rem 0.65rem;
      border-radius: 999px;
      color: #ffe6c6;
      background: rgba(255, 184, 107, 0.12);
      border: 1px solid rgba(255, 184, 107, 0.18);
      font-size: 0.84rem;
      font-weight: 600;
    }

    .editorial-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .editorial-card {
      display: grid;
      grid-template-rows: 160px auto;
      background: linear-gradient(180deg, rgba(21, 27, 39, 0.95), rgba(12, 15, 21, 0.95));
    }

    .editorial-card__media {
      background:
        radial-gradient(circle at 25% 25%, rgba(141, 220, 255, 0.24), transparent 26%),
        radial-gradient(circle at 76% 32%, rgba(255, 184, 107, 0.22), transparent 22%),
        linear-gradient(145deg, #1c2334, #0d1118 70%);
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    }

    .editorial-card:nth-child(2) .editorial-card__media {
      background:
        radial-gradient(circle at 20% 18%, rgba(194, 147, 255, 0.24), transparent 24%),
        radial-gradient(circle at 84% 28%, rgba(92, 200, 255, 0.22), transparent 20%),
        linear-gradient(145deg, #1c1930, #0d1118 72%);
    }

    .editorial-card:nth-child(3) .editorial-card__media {
      background:
        radial-gradient(circle at 18% 28%, rgba(255, 184, 107, 0.24), transparent 24%),
        radial-gradient(circle at 72% 26%, rgba(141, 220, 255, 0.18), transparent 24%),
        linear-gradient(145deg, #2a1b1d, #0d1118 72%);
    }

    .editorial-card__body {
      display: grid;
      gap: 0.75rem;
    }

    .kicker {
      color: var(--accent);
      font-size: 0.84rem;
      font-weight: 700;
      letter-spacing: 0.05em;
      text-transform: uppercase;
    }

    .section-card__note {
      margin-top: 1rem;
      color: var(--faint);
      font-size: 0.92rem;
    }

    footer {
      padding: 0 0 2rem;
      color: var(--muted);
    }

    .footer-card {
      border-top: 1px solid var(--border);
      padding-top: 1.2rem;
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .footer-card a {
      color: var(--muted);
    }

    @media (max-width: 960px) {
      .hero,
      .deals-grid {
        grid-template-columns: 1fr;
      }

      .products-grid,
      .editorial-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }

    @media (max-width: 720px) {
      .site-shell {
        width: min(var(--max), calc(100% - 1.2rem));
      }

      .header-bar,
      .topbar__inner,
      .section-head,
      .footer-card {
        align-items: start;
      }

      .header-bar,
      .section-head,
      .footer-card {
        flex-direction: column;
      }

      .hero__stats,
      .products-grid,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .deal-card {
        grid-template-columns: 1fr;
      }

      .deal-card__visual {
        min-height: 180px;
        border-right: 0;
        border-bottom: 1px solid rgba(255, 255, 255, 0.08);
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }
  </style>
</head>
