      .header-bar,
      .topbar__inner,
      .section-head,
      .footer-card {
        align-items: start;
      }

      .header-bar,
      .section-head,
      .footer-card {
        flex-direction: column;
      }

      .hero__stats,
      .products-grid,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .deal-card {
        grid-template-columns: 1fr;
      }

      .deal-card__visual {
        min-height: 180px;
        border-right: 0;
        border-bottom: 1px solid rgba(255, 255, 255, 0.08);
      }
