const { chromium } = require('playwright-core');
const path = require('path');
const { pathToFileURL } = require('url');
const axePath = require.resolve('axe-core/axe.min.js');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium' });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1600 } });
  await page.goto(pathToFileURL(path.resolve('index.html')).href, { waitUntil: 'load' });
  await page.addScriptTag({ path: axePath });
  const result = await page.evaluate(async () => await window.axe.run());
  const wcag = result.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = result.violations.filter(v => v.tags.includes('best-practice'));
  console.log(JSON.stringify({ wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })), bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) })) }, null, 2));
  await browser.close();
  process.exit(wcag.length ? 1 : 0);
})().catch(err => {
  console.error(err);
  process.exit(1);
});
