       height: 6rem;
       background: radial-gradient(circle, rgba(255, 184, 107, 0.95), rgba(255, 184, 107, 0.04) 70%, transparent 72%);
       box-shadow: 0 0 0 24px rgba(255, 184, 107, 0.06);
     }

     .feature-card__body,
     .deal-card__body,
     .editorial-card__body {
       padding: 1rem;
     }

     .product-meta,
     .deal-meta {
       display: flex;
       justify-content: space-between;
       gap: 1rem;
       color: var(--muted);
       font-size: 0.92rem;
       margin-bottom: 0.7rem;
     }

     .price {
       color: var(--text);
       font-weight: 700;
     }

     .feature-card h3,
     .deal-card h3,
     .editorial-card h3 {
       margin: 0 0 0.45rem;
       font-size: 1.12rem;
     }

     .feature-card p,
     .deal-card p,
     .editorial-card p {
       margin: 0;
       color: var(--muted);
     }

     .tag-row {
       display: flex;
       flex-wrap: wrap;
       gap: 0.45rem;
       margin-top: 0.85rem;
     }

     .tag {
       display: inline-flex;
       align-items: center;
       min-height: 32px;
       padding: 0.25rem 0.6rem;
       border-radius: 999px;
       font-size: 0.82rem;
       color: #d4def0;
       background: rgba(255, 255, 255, 0.05);
       border: 1px solid rgba(255, 255, 255, 0.08);
     }

     .deals-grid {
       grid-template-columns: 1.1fr 0.9fr 0.9fr;
     }

     .deal-card {
       display: grid;
       grid-template-columns: 0.95fr 1.05fr;
       min-height: 100%;
       background:
         radial-gradient(circle at top left, rgba(255, 184, 107, 0.14), transparent 34%),
         linear-gradient(180deg, rgba(24, 29, 42, 0.95), rgba(12, 15, 21, 0.95));
     }

     .deal-card__visual {
       min-height: 100%;
       background:
         radial-gradient(circle at 30% 28%, rgba(255, 255, 255, 0.15), transparent 18%),
         linear-gradient(160deg, rgba(92, 200, 255, 0.18), rgba(12, 15, 21, 0.12) 38%, rgba(255, 184, 107, 0.14));
       border-right: 1px solid rgba(255, 255, 255, 0.08);
       position: relative;
     }

     .deal-card__visual::after {
       content: "";
       position: absolute;
       inset: 18% 18%;
       border-radius: 20px;
       background:
         linear-gradient(145deg, rgba(10, 13, 19, 0.85), rgba(29, 36, 52, 0.92));
       border: 1px solid rgba(255, 255, 255, 0.08);
       box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
     }

     .deal-card--wide {
       grid-template-columns: 1fr;
     }

     .deal-card--wide .deal-card__visual {
       min-height: 180px;
       border-right: 0;
       border-bottom: 1px solid rgba(255, 255, 255, 0.08);
     }

     .deal-card--wide .deal-card__visual::after {
       inset: 18% 10% 20%;
     }

     .deal-card__body {
       display: grid;
       align-content: start;
       gap: 0.85rem;
     }

     .deal-card__footer {
       display: flex;
       flex-wrap: wrap;
       gap: 0.65rem;
       align-items: center;
       margin-top: 0.2rem;
     }

     .deal-card__footer .button {
       min-height: 42px;
       padding-inline: 0.85rem;
     }

     .deal-chip {
       display: inline-flex;
       align-items: center;
       gap: 0.45rem;
       width: fit-content;
       min-height: 34px;
       padding: 0.3rem 0.65rem;
       border-radius: 999px;
       color: #ffe6c6;
       background: rgba(255, 184, 107, 0.12);
       border: 1px solid rgba(255, 184, 107, 0.18);
       font-size: 0.84rem;
       font-weight: 600;
     }

     .editorial-grid {
       grid-template-columns: repeat(3, minmax(0, 1fr));
     }

     .editorial-card {
       display: grid;
       grid-template-rows: 160px auto;
       background: linear-gradient(180deg, rgba(21, 27, 39, 0.95), rgba(12, 15, 21, 0.95));
     }

     .editorial-card__media {
       background:
         radial-gradient(circle at 25% 25%, rgba(141, 220, 255, 0.24), transparent 26%),
         radial-gradient(circle at 76% 32%, rgba(255, 184, 107, 0.22), transparent 22%),
         linear-gradient(145deg, #1c2334, #0d1118 70%);
       border-bottom: 1px solid rgba(255, 255, 255, 0.08);
     }

     .editorial-card:nth-child(2) .editorial-card__media {
       background:
         radial-gradient(circle at 20% 18%, rgba(194, 147, 255, 0.24), transparent 24%),
         radial-gradient(circle at 84% 28%, rgba(92, 200, 255, 0.22), transparent 20%),
         linear-gradient(145deg, #1c1930, #0d1118 72%);
     }

     .editorial-card:nth-child(3) .editorial-card__media {
       background:
         radial-gradient(circle at 18% 28%, rgba(255, 184, 107, 0.24), transparent 24%),
         radial-gradient(circle at 72% 26%, rgba(141, 220, 255, 0.18), transparent 24%),
         linear-gradient(145deg, #2a1b1d, #0d1118 72%);
     }

     .editorial-card__body {
       display: grid;
       gap: 0.75rem;
     }

     .kicker {
       color: var(--accent);
       font-size: 0.84rem;
       font-weight: 700;
       letter-spacing: 0.05em;
       text-transform: uppercase;
     }

     .section-card__note {
       margin-top: 1rem;
       color: var(--faint);
       font-size: 0.92rem;
     }

     footer {
       padding: 0 0 2rem;
       color: var(--muted);
     }

     .footer-card {
       border-top: 1px solid var(--border);
       padding-top: 1.2rem;
       display: flex;
       justify-content: space-between;
       gap: 1rem;
       flex-wrap: wrap;
     }

     .footer-card a {
       color: var(--muted);
     }

     @media (max-width: 960px) {
       .hero,
       .deals-grid {
         grid-template-columns: 1fr;
       }

       .products-grid,
       .editorial-grid {
         grid-template-columns: repeat(2, minmax(0, 1fr));
       }
     }

     @media (max-width: 720px) {
       .site-shell {
         width: min(var(--max), calc(100% - 1.2rem));
       }

       .header-bar,
       .topbar__inner,
       .section-head,
       .footer-card {
         align-items: start;
       }

       .header-bar,
       .section-head,
       .footer-card {
         flex-direction: column;
       }

       .hero__stats,
       .products-grid,
       .editorial-grid {
         grid-template-columns: 1fr;
       }

       .deal-card {
         grid-template-columns: 1fr;
       }

       .deal-card__visual {
         min-height: 180px;
         border-right: 0;
         border-bottom: 1px solid rgba(255, 255, 255, 0.08);
       }
     }

     @media (prefers-reduced-motion: reduce) {
       html {
         scroll-behavior: auto;
       }

       *, *::before, *::after {
         animation-duration: 0.01ms !important;
         animation-iteration-count: 1 !important;
         transition-duration: 0.01ms !important;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>

   <div class="site-shell">
     <header>
       <div class="topbar" aria-label="Store announcement">
         <div class="topbar__inner">
           <span class="topbar__badge"><span class="topbar__dot" aria-hidden="true"></span>Free shipping on orders over $75</span>
           <span>New season arrivals are dropping daily</span>
         </div>
       </div>

       <div class="header-bar">
         <a class="brand" href="#maincontent">
           <span class="brand__mark" aria-hidden="true">A</span>
           <span>Aster &amp; Co.</span>
         </a>

         <nav aria-label="Primary">
           <ul>
             <li><a href="#featured">Featured</a></li>
             <li><a href="#deals">Deals</a></li>
             <li><a href="#stories">Stories</a></li>
             <li><a href="#discover">Discover</a></li>
           </ul>
         </nav>
       </div>
     </header>

     <main id="maincontent" tabindex="-1">
       <section class="hero" aria-labelledby="hero-title">
         <div class="hero__content">
           <span class="eyebrow">Retail, reimagined</span>
           <h1 id="hero-title">A sharper way to shop the season.</h1>
           <p class="lede">Curated essentials, limited-time savings, and editorial picks that make everyday purchases feel considered. Explore products built for a modern home, wardrobe, and routine.</p>
           <div class="hero__actions">
             <a class="button button--primary" href="#featured">Shop featured products</a>
             <a class="button button--secondary" href="#stories">Read the latest edit</a>
           </div>
           <div class="hero__stats" aria-label="Store highlights">
             <div class="stat"><strong>120+</strong><span>new arrivals this month</span></div>
             <div class="stat"><strong>4.9/5</strong><span>average customer rating</span></div>
             <div class="stat"><strong>48h</strong><span>average dispatch time</span></div>
           </div>
         </div>

         <section class="hero__panel" aria-label="Featured spotlight">
           <div class="spotlight">
             <div class="spotlight__visual" role="img" aria-label="Editorial product display of a sculpted chair, ambient lighting, and textured home accessories">
               <div class="spotlight__card">
                 <h2>Signature collection</h2>
                 <p>Minimal pieces in warm neutrals and cool metallic accents, designed to layer beautifully across your home.</p>
               </div>
             </div>
           </div>
         </section>
       </section>

       <section id="featured" class="sections" aria-labelledby="featured-title">
         <div class="section-card">
           <div class="section-head">
             <div>
               <span class="kicker">Featured products</span>
               <h2 id="featured-title">Design-forward essentials worth the spotlight.</h2>
             </div>
             <p>Three standout products across home, accessories, and daily carry — selected for their shape, function, and tactile finish.</p>
           </div>
           <div class="grid products-grid" id="featured-products"></div>
         </div>
       </section>

       <section id="deals" class="sections" aria-labelledby="deals-title">
         <div class="section-card">
           <div class="section-head">
             <div>
               <span class="kicker">Deals</span>
               <h2 id="deals-title">Limited-time offers with real momentum.</h2>
             </div>
             <p>Fresh markdowns on customer favorites, seasonal layers, and home upgrades — all selected to keep the sale section feel premium.</p>
           </div>
           <div class="grid deals-grid" id="deal-grid"></div>
         </div>
       </section>

       <section id="stories" class="sections" aria-labelledby="stories-title">
         <div class="section-card">
           <div class="section-head">
             <div>
               <span class="kicker">Editorial content</span>
               <h2 id="stories-title">Stories that help shoppers decide with confidence.</h2>
             </div>
             <p>Short reads on styling, materials, and what to buy now — built to feel like a magazine spread inside the store experience.</p>
           </div>
           <div class="grid editorial-grid" id="editorial-grid"></div>
           <p class="section-card__note">Every section keeps a clear heading structure, visible focus states, and mobile-friendly spacing for comfortable browsing.</p>
         </div>
       </section>
     </main>

     <footer>
       <div class="footer-card">
         <p>&copy; 2026 Aster &amp; Co. Curated retail for modern living.</p>
         <p><a href="#maincontent">Back to top</a></p>
       </div>
     </footer>
   </div>

   <script>
     const featuredProducts = [
       {
         name: "Halo Accent Chair",
         category: "Home",
         price: "$420",
         details: "Boucle texture, powder-coated frame, and a low silhouette for lounge-ready rooms.",
         tags: ["New", "Best seller", "Quick ship"]
       },
       {
         name: "Northbound Weekender",
         category: "Carry",
         price: "$158",
         details: "Structured canvas, leather trim, and a padded laptop sleeve for short trips.",
         tags: ["Travel", "Water resistant", "Limited run"]
       },
       {
         name: "Contour Table Lamp",
         category: "Lighting",
         price: "$96",
         details: "Soft diffusion and a weighted base create a calm, gallery-like glow at night.",
         tags: ["Warm light", "Metal finish", "Editor pick"]
       }
     ];

     const deals = [
       {
         title: "Spring reset bundle",
         label: "Up to 30% off",
         price: "Save $64",
         details: "Pair a textured throw, candle duo, and tray set for an easy room refresh.",
         variant: "deal-card--wide",
         cta: "Shop the bundle"
       },
       {
         title: "Daily carry essentials",
         label: "20% off through Sunday",
         price: "From $48",
         details: "Organizers and slim accessories built to streamline commutes and weekends.",
         cta: "Browse accessories"
       },
       {
         title: "Lighting favorites",
         label: "Buy one, save on the second",
         price: "Mix & match",
         details: "Soft-glow lamps and statement pieces that lift a room without overpowering it.",
         cta: "See lighting"
       }
     ];

     const stories = [
       {
         kicker: "Style guide",
         title: "How to layer neutrals without losing warmth",
         details: "A quick look at texture, contrast, and small accents that keep a quiet palette feeling alive."
       },
       {
         kicker: "Materials",
         title: "What makes a product feel premium in hand",
         details: "From finish to weight, learn the signals that separate everyday objects from lasting favorites."
       },
       {
         kicker: "Buy now",
         title: "Five gifts that work for almost anyone",
         details: "Simple, useful picks with strong presentation and year-round appeal."
       }
     ];

     const featuredRoot = document.getElementById("featured-products");
     const dealsRoot = document.getElementById("deal-grid");
     const storiesRoot = document.getElementById("editorial-grid");

     featuredRoot.innerHTML = featuredProducts.map((item) => `
       <article class="feature-card">
         <div class="feature-card__image" aria-hidden="true"></div>
         <div class="feature-card__body">
           <div class="product-meta">
             <span>${item.category}</span>
             <span class="price">${item.price}</span>
           </div>
           <h3>${item.name}</h3>
           <p>${item.details}</p>
           <div class="tag-row" aria-label="${item.name} highlights">
             ${item.tags.map((tag) => `<span class="tag">${tag}</span>`).join("")}
           </div>
         </div>
       </article>
     `).join("");

     dealsRoot.innerHTML = deals.map((item) => `
       <article class="deal-card ${item.variant || ""}">
         <div class="deal-card__visual" aria-hidden="true"></div>
         <div class="deal-card__body">
           <div class="deal-meta">
             <span class="deal-chip">${item.label}</span>
             <span class="price">${item.price}</span>
           </div>
           <h3>${item.title}</h3>
           <p>${item.details}</p>
           <div class="deal-card__footer">
             <a class="button button--secondary" href="#featured">${item.cta}</a>
           </div>
         </div>
       </article>
     `).join("");

     storiesRoot.innerHTML = stories.map((item) => `
       <article class="editorial-card">
         <div class="editorial-card__media" aria-hidden="true"></div>
         <div class="editorial-card__body">
           <span class="kicker">${item.kicker}</span>
           <h3>${item.title}</h3>
           <p>${item.details}</p>
         </div>
       </article>
     `).join("");
   </script>
 </body>
 </html>

')
